def figure(expr, de, a, pt, nom_pt):
    return {"type": "courbe", "titre": "La courbe (C_f) dans un repère orthonormé", "ratio": 1,
            "axes": {"x": {"min": -3, "max": 8, "nom": "x", "graduations": list(range(-2, 8, 2))},
                     "y": {"min": -3, "max": 8, "nom": "y", "graduations": list(range(-2, 8, 2))}},
            "legende": f"(C_f) sur I, le point {nom_pt} et la droite d'équation y = x (en pointillés).",
            "elements": [{"f": "courbe", "expr": expr, "de": de, "a": a, "couleur": "cyan", "texte": "(C_f)", "texte_x": a - 0.6, "pos": "no"},
                         {"f": "courbe", "expr": "x", "de": -3, "a": 8, "couleur": "faible", "trait": "pointille", "texte": "y = x", "texte_x": 7, "pos": "se"},
                         {"f": "point", "at": [de, eval(expr.replace("^", "**").replace("x", f"({de})"))], "couleur": "cyan"},
                         {"f": "point", "at": pt, "couleur": "jaune", "t": nom_pt, "pos": "no"}]}


